"""A launch tells the core WHICH ENGINE it runs, so the security state it copies into the profile was generated by that engine.

The core places the security state (intermediates, OneCRL, CRLite) in a profile inside `write_user_js`, and a generation is tied to the engine's build id. The server's one
call `write_user_js(profile, prefs)` named no engine, so the core fell back to the SEALED engine: with an engine the caller chose (`executable_path=`) the state was looked up
and, on a cold cache, generated for another binary. The launch passes `engine=<the executable it runs>`; `engine_argv` stays the core's default, because the line this launch
runs (`-juggler-pipe`, headed or headless, the caller's `args`) is not a line a generation may use.

Known-bad: the call without `engine=`; it reaches `ensure_security_state` with `engine=None`.
"""
from __future__ import annotations

import pytest

from invisible_core.juggler.connection import EventListeners
from invisible_playwright._juggler import server as module
from invisible_playwright._juggler.server import BrowserTypeDispatcher, JugglerServer
from _browser_census import closes_with_the_test


class _Engine(EventListeners):
    def __init__(self):
        EventListeners.__init__(self)
        closes_with_the_test(self)

    def send(self, method, params=None, session=None, timeout=30.0):
        return {"browserContextId": "ctx-1", "targetId": "t-1"}

    def startup_send(self, method, params=None):
        return self.send(method, params, timeout=None)

    def close(self, timeout=5.0):
        pass


def _launch(monkeypatch, **params):
    server = JugglerServer()
    server.attach(type("R", (), {"emit_message": lambda self, m: None})())
    monkeypatch.setattr(module.juggler, "launch", lambda executable, profile_dir, **kwargs: _Engine())
    try:
        BrowserTypeDispatcher(server).op_launch(dict({"executablePath": "the-engine-of-this-launch", "firefoxUserPrefs": {}}, **params))
    finally:
        server.shutdown()


@pytest.mark.unit
def test_the_launch_asks_the_core_for_the_security_state_of_the_engine_it_runs(monkeypatch):
    """Through the core's real `write_user_js` and `place_security_state`: what reaches `ensure_security_state` is the engine of the launch and no launch line."""
    import invisible_core._security_state as security_state

    seen = []
    monkeypatch.setattr(security_state, "ensure_security_state", lambda *a, **kw: seen.append(kw) or None)

    _launch(monkeypatch)

    assert len(seen) == 1, seen
    assert seen[0].get("engine") == "the-engine-of-this-launch"
    assert seen[0].get("engine_argv") is None, "the launch line of the session is not a generation's line"


@pytest.mark.unit
def test_the_engine_is_the_one_the_caller_chose_for_a_headed_launch_with_arguments_too(monkeypatch):
    import invisible_core._security_state as security_state

    seen = []
    monkeypatch.setattr(security_state, "ensure_security_state", lambda *a, **kw: seen.append(kw) or None)

    _launch(monkeypatch, headless=False, args=["-width", "800"])

    assert [(kw.get("engine"), kw.get("engine_argv")) for kw in seen] == [("the-engine-of-this-launch", None)]
